"""Curated diagnostic question bank.

Every objective question has one verifiable answer, an explanation and a validation
source. Answers are stored server-side only. Difficulty: 1 easy, 2 medium, 3 hard.
Answer formats:
  single / scenario: index of the correct choice
  multi:             sorted list of correct indices
  code_output / short_answer: {"accepted": [...]} compared after normalisation
  practical:         no key; evaluated against `rubric` (needs an AI provider)
"""


def q(id, skill, difficulty, qtype, prompt, answer, explanation, objective, source, *, topic, competency,
      choices=None, code=None, rubric=None):
    return dict(id=id, skill_id=skill, difficulty=difficulty, qtype=qtype, prompt=prompt, correct_answer=answer,
                explanation=explanation, learning_objective=objective, validation_source=source, topic=topic,
                competency=competency, choices=choices or [], code=code, rubric=rubric)


